"""
Flatten a nested dictionary using a thread pool for parallel task execution.

Each nested sub-dictionary is submitted as an independent task to a
ThreadPoolExecutor, so deeply nested or wide structures are processed
concurrently.
"""

from __future__ import annotations

from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import Any


def flatten_nested_dict(
    nested: dict[str, Any],
    *,
    separator: str = ".",
    max_workers: int | None = None,
) -> dict[str, Any]:
    """Flatten a nested dictionary into single-level dot-notation keys.

    Sub-dictionaries encountered at any depth are submitted to a thread pool
    so that independent branches of the tree are flattened in parallel.

    Args:
        nested: The dictionary to flatten. Values may be dicts at any depth.
        separator: Delimiter placed between key segments (default ``"."``).
        max_workers: Maximum threads in the pool. ``None`` lets Python choose.

    Returns:
        A new flat dictionary whose keys use dot-notation.

    Examples:
        >>> flatten_nested_dict({"a": {"b": 1, "c": {"d": 2}}})
        {'a.b': 1, 'a.c.d': 2}
    """
    if not isinstance(nested, dict):
        raise TypeError(f"Expected dict, got {type(nested).__name__}")

    result: dict[str, Any] = {}
    _flatten_parallel(nested, prefix="", separator=separator,
                      max_workers=max_workers, result=result)
    return result


def _flatten_parallel(
    d: dict[str, Any],
    *,
    prefix: str,
    separator: str,
    max_workers: int | None,
    result: dict[str, Any],
) -> None:
    """Recursively flatten *d*, dispatching sub-dicts to a thread pool."""
    futures = {}
    with ThreadPoolExecutor(max_workers=max_workers) as pool:
        for key, value in d.items():
            full_key = f"{prefix}{separator}{key}" if prefix else key
            if isinstance(value, dict):
                futures[pool.submit(
                    _flatten_worker, value,
                    prefix=full_key, separator=separator,
                    max_workers=max_workers,
                )] = full_key
            else:
                result[full_key] = value

        for future in as_completed(futures):
            result.update(future.result())


def _flatten_worker(
    d: dict[str, Any],
    *,
    prefix: str,
    separator: str,
    max_workers: int | None,
) -> dict[str, Any]:
    """Entry-point for each thread; returns a partial flat dict."""
    partial: dict[str, Any] = {}
    _flatten_parallel(d, prefix=prefix, separator=separator,
                      max_workers=max_workers, result=partial)
    return partial


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------

def test_flat_dict_passthrough():
    """A dict with no nesting is returned unchanged."""
    assert flatten_nested_dict({"a": 1, "b": 2}) == {"a": 1, "b": 2}


def test_one_level_nesting():
    assert flatten_nested_dict({"a": {"b": 1}}) == {"a.b": 1}


def test_multi_level_nesting():
    data = {"a": {"b": {"c": {"d": 42}}}}
    assert flatten_nested_dict(data) == {"a.b.c.d": 42}


def test_mixed_nested_and_flat():
    data = {"x": 1, "y": {"z": 2}}
    assert flatten_nested_dict(data) == {"x": 1, "y.z": 2}


def test_multiple_branches():
    data = {"a": {"b": 1}, "c": {"d": 2}}
    assert flatten_nested_dict(data) == {"a.b": 1, "c.d": 2}


def test_deep_branches():
    data = {"a": {"b": {"c": 1}}, "d": {"e": {"f": 2}}}
    assert flatten_nested_dict(data) == {"a.b.c": 1, "d.e.f": 2}


def test_list_values_are_preserved():
    """Lists are treated as leaf values, not recursively flattened."""
    data = {"a": {"b": [1, 2, 3]}}
    assert flatten_nested_dict(data) == {"a.b": [1, 2, 3]}


def test_none_value():
    assert flatten_nested_dict({"a": None}) == {"a": None}


def test_bool_value():
    data = {"flag": {"enabled": True, "verbose": False}}
    assert flatten_nested_dict(data) == {"flag.enabled": True, "flag.verbose": False}


def test_empty_dict():
    assert flatten_nested_dict({}) == {}


def test_nested_empty_dict():
    """An empty sub-dict produces no keys."""
    data = {"a": {}}
    assert flatten_nested_dict(data) == {}


def test_custom_separator():
    data = {"a": {"b": {"c": 1}}}
    assert flatten_nested_dict(data, separator="/") == {"a/b/c": 1}


def test_custom_separator_underscore():
    data = {"a": {"b": 1}}
    assert flatten_nested_dict(data, separator="_") == {"a_b": 1}


def test_numeric_keys():
    data = {"0": {"1": {"2": "deep"}}}
    assert flatten_nested_dict(data) == {"0.1.2": "deep"}


def test_special_character_keys():
    data = {"key-1": {"key_2": {"key.3": "val"}}}
    assert flatten_nested_dict(data) == {"key-1.key_2.key.3": "val"}


def test_large_flat_dict():
    """Thousands of top-level keys should still work correctly."""
    data = {f"k{i}": i for i in range(5000)}
    result = flatten_nested_dict(data)
    assert len(result) == 5000
    assert result["k0"] == 0
    assert result["k4999"] == 4999


def test_wide_nested_dict():
    """A single parent with many child dicts exercises the thread pool."""
    data = {"root": {f"child{i}": {"val": i} for i in range(200)}}
    result = flatten_nested_dict(data)
    assert len(result) == 200
    assert result["root.child0.val"] == 0
    assert result["root.child199.val"] == 199


def test_deeply_nested_single_chain():
    """A linear chain 20 levels deep."""
    d: dict[str, Any] = {"leaf": 99}
    for i in range(20):
        d = {f"level{i}": d}
    result = flatten_nested_dict(d)
    expected_key = ".".join(f"level{i}" for i in range(19, -1, -1)) + ".leaf"
    assert result == {expected_key: 99}


def test_thread_pool_actually_used():
    """Verify parallelism by checking that results are complete and correct
    even when many sub-dicts compete for threads."""
    data = {f"branch{i}": {f"sub{j}": i * 100 + j for j in range(50)}
            for i in range(50)}
    result = flatten_nested_dict(data, max_workers=4)
    assert len(result) == 2500
    assert result["branch0.sub0"] == 0
    assert result["branch49.sub49"] == 4949


def test_type_error_on_non_dict():
    import pytest
    with pytest.raises(TypeError, match="Expected dict"):
        flatten_nested_dict("not a dict")  # type: ignore[arg-type]


def test_type_error_on_list():
    import pytest
    with pytest.raises(TypeError, match="Expected dict"):
        flatten_nested_dict([1, 2, 3])  # type: ignore[arg-type]


def test_type_error_on_none():
    import pytest
    with pytest.raises(TypeError, match="Expected dict"):
        flatten_nested_dict(None)  # type: ignore[arg-type]


def test_max_workers_one():
    """Single-threaded mode should still produce correct results."""
    data = {"a": {"b": 1}, "c": {"d": 2}}
    assert flatten_nested_dict(data, max_workers=1) == {"a.b": 1, "c.d": 2}


def test_deterministic_result():
    """Running twice yields the same output (order-insensitive)."""
    data = {f"k{i}": {f"v{j}": j for j in range(20)} for i in range(20)}
    r1 = flatten_nested_dict(data)
    r2 = flatten_nested_dict(data)
    assert r1 == r2


def test_string_values():
    data = {"config": {"host": "localhost", "port": "8080"}}
    assert flatten_nested_dict(data) == {
        "config.host": "localhost",
        "config.port": "8080",
    }


def test_dict_with_dict_value_at_leaf():
    """Nested dicts that eventually resolve to a dict value at the leaf
    should not appear (the leaf dict is itself flattened)."""
    data = {"a": {"b": {"c": 1, "d": 2}}}
    result = flatten_nested_dict(data)
    assert "a.b" not in result
    assert result["a.b.c"] == 1
    assert result["a.b.d"] == 2


if __name__ == "__main__":
    import pytest
    pytest.main([__file__, "-v"])
